373	  // RUNNING : waiting for transaction finish
374	  //           when `dma_done` rises either enter ready or restart in circular mode
375	  //
376	
377	  always_comb begin
378	    dma_state_d = dma_state_q;
379	    case (dma_state_q)
380	      DMA_READY: begin
381	        if (dma_start_pending) begin
382	          dma_state_d = DMA_STARTING;
383	        end
384	      end
385	      DMA_STARTING: begin
386	        dma_state_d = DMA_RUNNING;
387	      end
388	      DMA_RUNNING: begin
389	        if (dma_done) begin
390	          if (circular_mode) dma_state_d = DMA_STARTING;
391	          else dma_state_d = DMA_READY;
392	        end
393	      end
394	    endcase
395	  end
