421	    if (~rst_ni) begin
422	      transaction_ifr <= '0;
423	    end else if (reg2hw.interrupt_en.transaction_done.q == 1'b1) begin
424	      // Enter here only if the transaction_done interrupt is enabled
425	      if (dma_done == 1'b1) begin
426	        transaction_ifr <= 1'b1;
427	      end else if (reg2hw.transaction_ifr.re == 1'b1) begin
428	        // If the IFR bit is read, we must clear the transaction_ifr
429	        transaction_ifr <= 1'b0;
430	      end
431	    end
432	  end
433	
434	  /* Delayed transaction interrupt signals */
435	  always_ff @(posedge clk_cg, negedge rst_ni) begin : proc_ff_intr
436	    if (~rst_ni) begin
437	      dma_done_intr_n <= '0;
438	    end else begin
439	      dma_done_intr_n <= dma_done_intr;
440	    end
441	  end
442	
443	  /* Window IFR update */
444	  always_ff @(posedge clk_cg, negedge rst_ni) begin : proc_ff_window_ifr
445	    if (~rst_ni) begin
446	      window_ifr <= '0;
447	    end else if (reg2hw.interrupt_en.window_done.q == 1'b1) begin
448	      // Enter here only if the window_done interrupt is enabled
449	      if (window_event == 1'b1) begin
450	        window_ifr <= 1'b1;
451	      end else if (reg2hw.window_ifr.re == 1'b1) begin
452	        // If the IFR bit is read, we must clear the window_ifr
453	        window_ifr <= 1'b0;
454	      end
455	    end
456	  end
457	
458	  /* Delayed window interrupt signals */
459	  always_ff @(posedge clk_cg, negedge rst_ni) begin : proc_ff_window_intr
460	    if (~rst_ni) begin
461	      dma_window_intr_n <= '0;
462	    end else begin
463	      dma_window_intr_n <= dma_window_intr;
464	    end
465	  end
466	
467	  /* Window event counter */
468	  always_ff @(posedge clk_cg, negedge rst_ni) begin : proc_dma_window_cnt
469	    if (~rst_ni) begin
470	      window_counter <= '0;
471	    end else begin
472	      if (|reg2hw.window_size.q) begin
473	        if ( (circular_mode && reg2hw.window_size.qe) || (~circular_mode && (dma_start | dma_done))) begin
474	          window_counter <= '0;
475	        end else if (data_out_gnt) begin
476	          if (window_event) begin
477	            window_counter <= '0;
478	          end else begin
479	            window_counter <= window_counter + 'h1;
480	          end
481	        end
482	      end
483	    end
484	  end
485	
486	  /* Update Processing Unit start signal */
487	  always_ff @(posedge clk_cg, negedge rst_ni) begin
488	    if (~rst_ni) begin
489	      dma_processing_unit_on <= 1'b0;
490	    end else begin
491	      if (dma_start == 1'b1) begin
492	        dma_processing_unit_on <= 1'b1;
493	      end else if (dma_done == 1'b1) begin
494	        dma_processing_unit_on <= 1'b0;
495	      end
496	    end
497	  end
498	
499	  /* HW FIFO done signal override logic */
500	`ifdef HW_FIFO_MODE_EN
501	  assign dma_write_done_override = (write_buffer_empty & hw_fifo_done_i & hw_fifo_mode) || ext_dma_stop_i;
502	`else
503	  assign dma_write_done_override = ext_dma_stop_i;
504	`endif
505	
506	  assign dma_read_done_override = ext_dma_stop_i;
507	
508	
509	  /*_________________________________________________________________________________________________________________________________ */
510	
511	  /* Signal assignments */
512	
513	  /* General signals */
514	  assign dma_done_o = dma_done;
515	  assign dma_start = (dma_state_q == DMA_STARTING);
516	
517	  /* OBI signals */
518	  assign dma_read_req_o.req = data_in_req;
519	  assign dma_read_req_o.we = data_in_we;
520	  assign dma_read_req_o.be = data_in_be;
521	  assign dma_read_req_o.addr = data_in_addr;
522	  assign dma_read_req_o.wdata = 32'h0;
523	
524	  assign data_in_gnt = dma_read_resp_i.gnt;
525	  assign data_in_rvalid = dma_read_resp_i.rvalid;
526	  assign data_in_rdata = dma_read_resp_i.rdata;
527	
528	  assign dma_addr_req_o.req = data_addr_in_req;
529	  assign dma_addr_req_o.we = data_addr_in_we;
530	  assign dma_addr_req_o.be = data_addr_in_be;
531	  assign dma_addr_req_o.addr = data_addr_in_addr;
532	  assign dma_addr_req_o.wdata = 32'h0;
533	
534	  assign data_addr_in_gnt = dma_addr_resp_i.gnt;
535	  assign data_addr_in_rvalid = dma_addr_resp_i.rvalid;
536	  assign data_addr_in_rdata = dma_addr_resp_i.rdata;
537	
538	  assign dma_write_req_o.req = data_out_req;
539	  assign dma_write_req_o.we = data_out_we;
540	  assign dma_write_req_o.be = data_out_be;
541	  assign dma_write_req_o.addr = data_out_addr;
542	  assign dma_write_req_o.wdata = data_out_wdata;
543	
544	  assign data_out_gnt = dma_write_resp_i.gnt;
545	  assign data_out_rvalid = dma_write_resp_i.rvalid;
546	  assign data_out_rdata = dma_write_resp_i.rdata;
547	
548	  /* FIFO signals */
549	  assign read_buffer_req.push = data_in_rvalid;
550	  assign read_buffer_req.pop = read_buffer_pop;
551	  assign read_buffer_req.flush = general_buffer_flush;
552	  assign read_buffer_req.data = read_buffer_input;
553	
554	  assign read_buffer_empty = read_buffer_resp.empty;
555	  assign read_buffer_full = read_buffer_resp.full;
556	  assign read_buffer_alm_full = read_buffer_resp.alm_full;
557	  assign read_buffer_output = read_buffer_resp.data;
558	
559	  assign read_addr_buffer_req.push = data_addr_in_rvalid;
560	  assign read_addr_buffer_req.pop = data_out_gnt && address_mode;
561	  assign read_addr_buffer_req.flush = general_buffer_flush;
562	  assign read_addr_buffer_req.data = data_addr_in_rdata;
563	
564	  assign read_addr_buffer_empty = read_addr_buffer_resp.empty;
565	  assign read_addr_buffer_full = read_addr_buffer_resp.full;
566	  assign read_addr_buffer_alm_full = read_addr_buffer_resp.alm_full;
567	  assign read_addr_buffer_output = read_addr_buffer_resp.data;
568	
569	  assign write_buffer_req.push = write_buffer_push;
570	  assign write_buffer_req.pop = (dma_state_q == DMA_RUNNING) & data_out_gnt;
571	  assign write_buffer_req.flush = general_buffer_flush;
572	  assign write_buffer_req.data = write_buffer_input;
573	
574	  assign write_buffer_empty = write_buffer_resp.empty;
575	  assign write_buffer_full = write_buffer_resp.full;
576	  assign write_buffer_alm_full = write_buffer_resp.alm_full;
577	  assign write_buffer_output = write_buffer_resp.data;
578	
579	  assign dma_done_intr = transaction_ifr;
580	  assign dma_done_intr_o = dma_done_intr_n;
581	  assign dma_window_intr = window_ifr;
582	  assign dma_window_intr_o = dma_window_intr_n;
583	
584	  always_comb begin
585	    hw2reg = '0;
586	
587	    if (reg2hw.hw_config_mode.q) begin
588	      hw2reg = external_hw2reg_i;
589	    end
590	    //these registers are controlled only by the DMA and never externally
591	    //thus, they are overwritten
592	    hw2reg.transaction_ifr.d = transaction_ifr;
593	    hw2reg.window_ifr.d = window_ifr;
594	    hw2reg.status.ready.d = (dma_state_q == DMA_READY);
595	    hw2reg.status.window_done.d = window_event;
596	    hw2reg.window_count.d = window_counter[7:0];
597	  end
598	
599	
600	  assign circular_mode = reg2hw.mode.q == 1;
601	  assign address_mode = reg2hw.mode.q == 2;
602	  assign hw_fifo_mode = reg2hw.hw_fifo_en.q;
603	
604	  assign wait_for_rx = |(reg2hw.slot.rx_trigger_slot.q[SLOT_NUM-1:0] & (~trigger_slot_i));
605	  assign wait_for_tx = |(reg2hw.slot.tx_trigger_slot.q[SLOT_NUM-1:0] & (~trigger_slot_i));
606	  assign enable_wait_for_rx = |(reg2hw.slot.rx_trigger_slot.q[SLOT_NUM-1:0]);
607	  assign enable_wait_for_tx = |(reg2hw.slot.tx_trigger_slot.q[SLOT_NUM-1:0]);
608	
609	  /* Logic for window counter */
610	  //TODO: is it really necessary? Do we need to write into a register how many events are done?
611	  //      Or do we need only the window donw signal?
612	  assign window_event = |reg2hw.window_size.q & data_out_gnt & (window_counter == {19'h0, reg2hw.window_size.q});
613	
614	endmodule : dma

