 11	
 12	module dma_write_unit
 13	  import dma_reg_pkg::*;
 14	#(
 15	) (
 16	    input logic clk_i,
 17	    input logic rst_ni,
 18	
 19	    input dma_reg2hw_t reg2hw_i,
 20	
 21	    input logic dma_start_i,
 22	    input logic wait_for_tx_i,
 23	    input logic enable_wait_for_tx_i,
 24	    input logic [7:0] slot_wait_counter_i,
 25	
 26	    input logic dma_done_override_i,
 27	
 28	    input logic write_buffer_empty_i,
 29	    input logic read_addr_buffer_empty_i,
 30	
 31	    input logic [31:0] write_buffer_output_i,
 32	    input logic [31:0] read_addr_buffer_output_i,
 33	
 34	    input logic data_out_gnt_i,
 35	    input logic data_out_rvalid_i,
 36	
 37	    output logic data_out_req_o,
 38	    output logic data_out_we_o,
 39	    output logic [3:0] data_out_be_o,
 40	    output logic [31:0] data_out_addr_o,
 41	    output logic [31:0] data_out_wdata_o,
 42	
 43	    output logic dma_done_o
 44	);
 45	
 46	  /*_________________________________________________________________________________________________________________________________ */
 47	
 48	  /* Parameter definition */
 49	
 50	  import dma_reg_pkg::*;
 51	  import dma_pkg::*;
 52	  `include "dma_conf.svh"
 53	
 54	  /*_________________________________________________________________________________________________________________________________ */
 55	
 56	  /* Signals declaration */
 57	
 58	  /* Registers */
 59	  dma_reg2hw_t reg2hw;
 60	
 61	  logic dma_conf_1d;
 62	  logic dma_conf_2d;
 63	  logic dma_done;
 64	  logic address_mode;
 65	  logic dma_start;
 66	
 67	  enum logic {
 68	    DMA_WRITE_UNIT_IDLE,
 69	    DMA_WRITE_UNIT_ON
 70	  }
 71	      dma_write_unit_state, dma_write_unit_n_state;
 72	
 73	  dma_pkg::dma_data_type_t dst_data_type;
 74	
 75	  logic data_req_cond, data_req_cond_preobi;
 76	  logic dma_done_override;
 77	
 78	  logic data_out_req;
 79	  logic data_out_we;
 80	  logic data_out_gnt;
 81	  logic data_out_rvalid;
 82	  logic [31:0] data_out_addr;
 83	  logic [31:0] data_out_wdata;
 84	  logic [31:0] write_address;
 85	  logic [31:0] write_ptr_reg;
 86	  logic [3:0] byte_enable_out;
 87	
 88	  logic [31:0] dma_dst_d1_inc;
 89	  logic [31:0] dma_dst_d2_inc;
 90	  logic [16:0] dma_dst_cnt_d1;
 91	  logic [16:0] dma_dst_cnt_d2;
 92	
 93	  logic [16:0] dma_size_d1;
 94	  logic [16:0] dma_size_d2;
 95	
 96	  logic wait_for_tx;
 97	
 98	  /* FIFO signals */
 99	  logic write_buffer_empty;
100	  logic read_addr_buffer_empty;
101	  logic [31:0] write_buffer_data;
102	
103	  dma_pkg::dma_obi_state_type_t obi_data_req_q, obi_data_req_d;
104	
105	  dma_pkg::dma_wait_for_state_type_t wait_for_tx_state_q, wait_for_tx_state_d;
106	
107	  logic [7:0] slot_wait_counter_d, slot_wait_counter_q;
108	
109	  /*_________________________________________________________________________________________________________________________________ */
110	
111	  /* FSMs instantiation */
112	
113	  /* Sign extension of the increments */
114	  always_comb begin
115	    dma_dst_d1_inc = {{26{reg2hw.dst_ptr_inc_d1.q[5]}}, reg2hw.dst_ptr_inc_d1.q};
116	    dma_dst_d2_inc = {{9{reg2hw.dst_ptr_inc_d2.q[22]}}, reg2hw.dst_ptr_inc_d2.q};
117	  end
118	
119	  /* Request signal logic */
120	  always_comb begin : proc_req_signal_logic
121	    data_out_req = 0;
122	
123	    if (dma_write_unit_state == DMA_WRITE_UNIT_ON && dma_done == 1'b0) begin
124	      if (data_req_cond == 1'b1) begin
125	        data_out_req = 1;
126	      end
127	    end
128	  end
129	
130	  /* Counters for the writing fsm */
131	  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_dma_dst_cnt_reg
132	    if (~rst_ni) begin
133	      dma_dst_cnt_d1 <= '0;
134	      dma_dst_cnt_d2 <= '0;
135	      obi_data_req_q <= OBI_DATA_REQ;
136	      wait_for_tx_state_q <= WAIT_FOR_OUTSTANDING_IDLE;
137	      slot_wait_counter_q <= '0;
138	    end else begin
139	      obi_data_req_q <= obi_data_req_d;
140	      wait_for_tx_state_q <= wait_for_tx_state_d;
141	      slot_wait_counter_q <= slot_wait_counter_d;
142	      if (dma_start == 1'b1) begin
143	        dma_dst_cnt_d1 <= dma_size_d1;
144	        dma_dst_cnt_d2 <= dma_size_d2;
145	      end else if (dma_done == 1'b1 || dma_done_override == 1'b1) begin
146	        dma_dst_cnt_d1 <= '0;
147	        dma_dst_cnt_d2 <= '0;
148	      end else if ((data_out_gnt && data_out_req)) begin
149	        if (dma_conf_1d == 1'b1) begin
150	          // 1D case
151	          dma_dst_cnt_d1 <= dma_dst_cnt_d1 - 1;
152	        end else if (dma_conf_2d == 1'b1) begin
153	          // 2D case
154	          if (dma_dst_cnt_d1 == 1) begin
155	            // In this case, the d1 is finished, so we need to reset the d2 size
156	            dma_dst_cnt_d1 <= dma_size_d1;
157	            dma_dst_cnt_d2 <= dma_dst_cnt_d2 - 1;
158	          end else begin
159	            // In this case, the d1 isn't finished, so we need to decrement the d1 size
160	            dma_dst_cnt_d1 <= dma_dst_cnt_d1 - 1;
161	          end
162	        end
163	      end
164	    end
165	  end
166	
167	  /* Determine the byte enable depending on the datatype */
168	  always_comb begin : proc_byte_enable_out
169	    case (dst_data_type)  // Data type 00 Word, 01 Half word, 11,10 byte
170	      DMA_DATA_TYPE_WORD: byte_enable_out = 4'b1111;  // Writing a word (32 bits)
171	
172	      DMA_DATA_TYPE_HALF_WORD: begin  // Writing a half-word (16 bits)
173	        case (write_ptr_reg[1])
174	          1'b0: byte_enable_out = 4'b0011;
175	          1'b1: byte_enable_out = 4'b1100;
176	        endcase
177	        ;  // case(write_ptr_reg[1:0])
178	      end
179	
180	      DMA_DATA_TYPE_BYTE, DMA_DATA_TYPE_BYTE_: begin  // Writing a byte (8 bits)
181	        case (write_ptr_reg[1:0])
182	          2'b00: byte_enable_out = 4'b0001;
183	          2'b01: byte_enable_out = 4'b0010;
184	          2'b10: byte_enable_out = 4'b0100;
185	          2'b11: byte_enable_out = 4'b1000;
186	        endcase
187	        ;  // case(write_ptr_reg[1:0])
188	      end
189	    endcase
190	    ;  // case (dst_data_type)
191	  end
192	
193	  /* Store output data pointer and increment everytime write request is granted */
194	  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_ptr_out_reg
195	    if (~rst_ni) begin
196	      write_ptr_reg <= '0;
197	    end else begin
198	      if (dma_start == 1'b1) begin
199	        write_ptr_reg <= reg2hw.dst_ptr.q;
200	      end else if ((data_out_gnt && data_out_req)) begin
201	        if (dma_conf_1d == 1'b1) begin
202	          write_ptr_reg <= write_ptr_reg + dma_dst_d1_inc;
203	        end else if (dma_conf_2d == 1'b1) begin
204	          if (dma_dst_cnt_d1 == 1) begin
205	            // In this case, the d1 is finished, so we need to increment the pointer by sizeof(d1)*data_unit*strides
206	            write_ptr_reg <= write_ptr_reg + dma_dst_d2_inc;
207	          end else begin
208	            write_ptr_reg <= write_ptr_reg + dma_dst_d1_inc; // Increment just of one du, since we need to increase the 1d
209	          end
210	        end
211	      end
212	    end
213	  end
214	
215	  /* FSM state update */
216	  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_fsm_state
217	    if (~rst_ni) begin
218	      dma_write_unit_state <= DMA_WRITE_UNIT_IDLE;
219	    end else begin
220	      dma_write_unit_state <= dma_write_unit_n_state;
221	    end
222	  end
223	
224	  /* Write master FSM */
225	  always_comb begin : proc_dma_write_unit_logic
226	
227	    dma_write_unit_n_state = dma_write_unit_state;
228	    dma_done = 1'b0;
229	
230	    unique case (dma_write_unit_state)
231	
232	      DMA_WRITE_UNIT_IDLE: begin
233	        if (dma_start == 1'b1) begin
234	          dma_write_unit_n_state = DMA_WRITE_UNIT_ON;
235	        end
236	      end
237	      DMA_WRITE_UNIT_ON: begin
238	        // If all data has been written, exit
239	        if (dma_done_override == 1'b0) begin
240	          if (dma_conf_1d == 1'b1) begin
241	            // 1D DMA case
242	            if (|dma_dst_cnt_d1 == 1'b0) begin
243	              dma_write_unit_n_state = DMA_WRITE_UNIT_IDLE;
244	              dma_done = 1'b1;
245	            end
246	          end else if (dma_conf_2d == 1'b1) begin
247	            // 2D DMA case: exit only if 2d counter is 0
248	            if (|dma_dst_cnt_d2 == 1'b0) begin
249	              dma_write_unit_n_state = DMA_WRITE_UNIT_IDLE;
250	              dma_done = 1'b1;
251	            end
252	          end
253	        end else begin
254	          dma_write_unit_n_state = DMA_WRITE_UNIT_IDLE;
255	          dma_done = 1'b1;
256	        end
257	      end
258	
259	      default: ;
260	    endcase
261	  end
262	
263	  /* This logic performs the output data shitf to depending on the destination address, i.e. depending on BE */
264	  always_comb begin
265	    data_out_wdata = '0;
266	
267	    case (byte_enable_out)
268	      (4'b0011): begin
269	        data_out_wdata[15:0] = write_buffer_data[15:0];
270	      end
271	
272	      (4'b1100): begin
273	        data_out_wdata[31:16] = write_buffer_data[15:0];
274	      end
275	
276	      (4'b0001): begin
277	        data_out_wdata[7:0] = write_buffer_data[7:0];
278	      end
279	
280	      (4'b0010): begin
281	        data_out_wdata[15:8] = write_buffer_data[7:0];
282	      end
283	
284	      (4'b0100): begin
285	        data_out_wdata[23:16] = write_buffer_data[7:0];
286	      end
287	
288	      (4'b1000): begin
289	        data_out_wdata[31:24] = write_buffer_data[7:0];
290	      end
291	
292	      (4'b1111): begin
293	        data_out_wdata = write_buffer_data;
294	      end
295	
296	      default: ;
297	    endcase
298	  end
299	
300	  always_comb begin
301	    data_req_cond  = data_req_cond_preobi;
302	    obi_data_req_d = obi_data_req_q;
303	    unique case (obi_data_req_q)
304	
305	      OBI_DATA_REQ: begin
306	        if (data_out_req && !data_out_gnt) obi_data_req_d = OBI_WAIT_GNT;
307	      end
308	
309	      OBI_WAIT_GNT: begin
310	        data_req_cond  = 1'b1;
311	        obi_data_req_d = data_out_gnt ? OBI_DATA_REQ : OBI_WAIT_GNT;
312	      end
313	    endcase
314	  end
315	
316	  always_comb begin
317	    wait_for_tx_state_d = wait_for_tx_state_q;
318	    wait_for_tx = wait_for_tx_i;
319	    slot_wait_counter_d = slot_wait_counter_q;
320	
321	    unique case (wait_for_tx_state_q)
322	
323	      WAIT_FOR_OUTSTANDING_IDLE: begin
324	        if (enable_wait_for_tx_i) begin
325	          wait_for_tx_state_d = (data_out_req && data_out_gnt) ? WAIT_FOR_OUTSTANDING_WAIT : WAIT_FOR_OUTSTANDING_IDLE;
326	          slot_wait_counter_d = slot_wait_counter_i;
327	        end
328	      end
329	
330	      WAIT_FOR_OUTSTANDING_WAIT: begin
331	        wait_for_tx = 1'b1;
332	        if (data_out_rvalid) begin
333	          if (slot_wait_counter_q == '0) begin
334	            wait_for_tx_state_d = WAIT_FOR_OUTSTANDING_IDLE;
335	          end else begin
336	            wait_for_tx_state_d = WAIT_FOR_OUTSTANDING_COUNTER;
337	          end
338	        end
339	      end
340	
341	      WAIT_FOR_OUTSTANDING_COUNTER: begin
342	        wait_for_tx = 1'b1;
343	        if (slot_wait_counter_q == '0) begin
344	          wait_for_tx_state_d = WAIT_FOR_OUTSTANDING_IDLE;
345	        end else begin
346	          wait_for_tx_state_d = WAIT_FOR_OUTSTANDING_COUNTER;
347	          slot_wait_counter_d = slot_wait_counter_q - 1;
348	        end
349	      end
350	
351	      default: ;
352	
353	    endcase
354	
355	  end
356	
357	  /*_________________________________________________________________________________________________________________________________ */
358	
359	  /* Signal assignments */
360	  assign data_req_cond_preobi = (write_buffer_empty == 1'b0 && wait_for_tx == 1'b0 && (read_addr_buffer_empty && address_mode) == 1'b0);
