150	        dma_src_cnt_d2 <= {1'h0, reg2hw.size_d2.q};
151	      end else if (dma_done_i == 1'b1 || dma_done_override == 1'b1) begin
152	        dma_src_cnt_d1 <= '0;
153	        dma_src_cnt_d2 <= '0;
154	      end else if (data_in_gnt && data_in_req) begin
155	        if (dma_conf_1d == 1'b1) begin
