194	      read_ptr_reg <= '0;
195	    end else begin
196	      if (dma_start == 1'b1) begin
197	        read_ptr_reg <= reg2hw.src_ptr.q;
198	      end else if (data_in_gnt && data_in_req) begin
199	        if (dma_conf_1d == 1'b1) begin
200	          /* Increase the pointer by the amount written in ptr_inc */
201	          read_ptr_reg <= read_ptr_reg + dma_src_d1_inc;
202	        end else if (dma_conf_2d == 1'b1) begin
203	          if (read_ptr_update_sel == 1'b0) begin
204	            if (dma_src_cnt_d1 == 1 && |dma_src_cnt_d2 == 1'b1) begin
