206	              read_ptr_reg <= read_ptr_reg + dma_src_d2_inc;
207	            end else begin
208	              read_ptr_reg <= read_ptr_reg + dma_src_d1_inc; /* Increment of the d1 increment (stride) */
209	            end
210	          end else begin
211	            /* In this case, perform the transposition */
212	            if (dma_src_cnt_d1 == 1 && |dma_src_cnt_d2 == 1'b1) begin
213	              /* In this case, the d1 is almost finished, so we need to increment the pointer by sizeof(d1)*data_unit */
214	              read_ptr_reg <= trsp_src_ptr_reg;
215	            end else begin
216	              read_ptr_reg <= read_ptr_reg + dma_src_d2_inc; /* Increment of the d2 increment (stride) */
217	            end
218	          end
219	        end
220	      end
221	    end
222	  end
