243	    unique case (dma_read_unit_state)
244	
245	      DMA_READ_UNIT_IDLE: begin
246	        // Wait for start signal
247	        if (dma_start == 1'b1) begin
248	          buffer_flush = 1'b1;
249	          dma_read_unit_n_state = DMA_READ_UNIT_ON;
