260	              dma_read_done = 1'b1;
261	            end
262	          end else if (dma_conf_2d == 1'b1) begin
263	            // 2D DMA case: exit only if both 1d and 2d counters are at 0
264	            if (dma_src_cnt_d1 == {1'h0, reg2hw.size_d1.q} && |dma_src_cnt_d2 == 1'b0) begin
265	              dma_read_unit_n_state = DMA_READ_UNIT_IDLE;
266	              dma_read_done = 1'b1;
267	            end
268	          end
269	        end else begin
270	          dma_read_unit_n_state = DMA_READ_UNIT_IDLE;
271	        end
272	      end
273	    endcase
274	  end
275	
276	  /* Request logic of the read FSM */
277	  always_comb begin : proc_req_fsm_state_logic
278	    data_in_req = 0;
279	
280	    if (dma_read_unit_state == DMA_READ_UNIT_ON) begin
281	      if (data_req_cond == 1'b1) begin
282	        data_in_req = 1;
283	      end
284	    end
285	  end
286	
287	  /* This small FIFO is used to hold the last 2 LSBs of the read address.
288	   * Each time that a GNT is received, the current address is pushed.
289	   * Each time that a RVALID is received, the value is popped.
290	   * This feature enables the DMA to support outstanding transactions, 
291	   * when in the future this feature will be added to X-HEEP.
292	   */
293	  fifo_v3 #(
294	      .DEPTH(RVALID_FIFO_DEPTH),
295	      .FALL_THROUGH(1'b0),
296	      .DATA_WIDTH(2)
297	  ) dma_read_data_offset_fifo_i (
298	      .clk_i,
299	      .rst_ni,
300	      .flush_i(buffer_flush),
301	      .testmode_i(1'b0),
302	      .full_o(read_data_offset_full),
303	      .empty_o(),
304	      .usage_o(read_data_offset_usage),
305	      .data_i(read_ptr_reg[1:0]),
306	      .push_i(data_in_gnt && data_in_req),
307	      .data_o(read_data_offset),
308	      .pop_i(data_in_rvalid)
309	  );
310	
311	  /* This logic is used to put extract relevant data from the word read and to perform sign extension */
312	  always_comb begin : proc_input_data
313	    read_buffer_input = data_in_rdata;
314	
315	    if (subaddr_mode == 1'b0) begin
316	      case (read_data_offset)
317	        2'b00: begin
318	          if (src_data_type == DMA_DATA_TYPE_BYTE) begin
319	            read_buffer_input = {{24{sign_ext & data_in_rdata[7]}}, data_in_rdata[7:0]};
320	          end else if (src_data_type == DMA_DATA_TYPE_HALF_WORD) begin
321	            read_buffer_input = {{16{sign_ext & data_in_rdata[15]}}, data_in_rdata[15:0]};
322	          end
323	        end
324	        // Only BYTE could cause the address to be 01
325	        2'b01: begin
326	          read_buffer_input = {{24{sign_ext & data_in_rdata[15]}}, data_in_rdata[15:8]};
327	        end
328	
329	        2'b10: begin
330	          if (src_data_type == DMA_DATA_TYPE_BYTE) begin
331	            read_buffer_input = {{24{sign_ext & data_in_rdata[23]}}, data_in_rdata[23:16]};
332	          end else if (src_data_type == DMA_DATA_TYPE_HALF_WORD) begin
333	            read_buffer_input = {{16{sign_ext & data_in_rdata[31]}}, data_in_rdata[31:16]};
334	          end
335	        end
336	        // Again, only BYTE could cause the address to be 01
337	        2'b11: read_buffer_input = {{24{sign_ext & data_in_rdata[31]}}, data_in_rdata[31:24]};
338	      endcase
339	    end
340	  end
