343	
344	  /* Signal assignments */
345	  assign sign_ext = reg2hw_i.sign_ext.q;
346	  assign data_in_we = 0;
347	  assign data_in_be = 4'b1111;
348	  assign data_in_addr = read_ptr_reg;
349	
350	  generate
351	    if (RVALID_FIFO_DEPTH != 1) begin : gen_rvalid_fifo
352	      assign read_data_offset_alm_full = (read_data_offset_usage == LastFifoUsage[AddrFifoDepth-1:0]);
353	      assign data_req_cond_preobi = (dma_read_done == 1'b0 && buffer_full == 1'b0 && buffer_alm_full == 1'b0 && 
354	                          read_data_offset_full == 1'b0 && read_data_offset_alm_full == 1'b0 &&
355	                          wait_for_rx == 1'b0);
356	    end else begin : gen_no_rvalid_fifo
357	      assign read_data_offset_alm_full = 1'b0;
358	      assign data_req_cond_preobi = (dma_read_done == 1'b0 && buffer_full == 1'b0 && buffer_alm_full == 1'b0 && 
359	                          wait_for_rx == 1'b0);
360	    end
361	  endgenerate
362	
363	  always_comb begin
364	    data_req_cond  = data_req_cond_preobi;
365	    obi_data_req_d = obi_data_req_q;
366	    unique case (obi_data_req_q)
367	
368	      OBI_DATA_REQ: begin
369	        if (data_in_req && !data_in_gnt) obi_data_req_d = OBI_WAIT_GNT;
370	      end
371	
372	      OBI_WAIT_GNT: begin
373	        data_req_cond  = 1'b1;
374	        obi_data_req_d = data_in_gnt ? OBI_DATA_REQ : OBI_WAIT_GNT;
375	      end
376	    endcase
377	  end
378	
379	  always_comb begin
380	    wait_for_rx_state_d = wait_for_rx_state_q;
381	    wait_for_rx = wait_for_rx_i;
382	    slot_wait_counter_d = slot_wait_counter_q;
383	
384	    unique case (wait_for_rx_state_q)
385	
386	      WAIT_FOR_OUTSTANDING_IDLE: begin
387	        if (enable_wait_for_rx_i) begin
388	          wait_for_rx_state_d = (data_in_req && data_in_gnt) ? WAIT_FOR_OUTSTANDING_WAIT : WAIT_FOR_OUTSTANDING_IDLE;
389	          slot_wait_counter_d = slot_wait_counter_i;
390	        end
391	      end
392	
393	      WAIT_FOR_OUTSTANDING_WAIT: begin
394	        wait_for_rx = 1'b1;
395	        if (data_in_rvalid) begin
396	          if (slot_wait_counter_q == '0) begin
397	            wait_for_rx_state_d = WAIT_FOR_OUTSTANDING_IDLE;
398	          end else begin
399	            wait_for_rx_state_d = WAIT_FOR_OUTSTANDING_COUNTER;
400	          end
401	        end
402	      end
403	
404	      WAIT_FOR_OUTSTANDING_COUNTER: begin
405	        wait_for_rx = 1'b1;
406	        if (slot_wait_counter_q == '0) begin
407	          wait_for_rx_state_d = WAIT_FOR_OUTSTANDING_IDLE;
408	        end else begin
409	          wait_for_rx_state_d = WAIT_FOR_OUTSTANDING_COUNTER;
410	          slot_wait_counter_d = slot_wait_counter_q - 1;
411	        end
412	      end
413	
414	      default: ;
415	
416	    endcase
417	  end
418	
419	  /* Renaming */
420	  assign reg2hw = reg2hw_i;
421	  assign data_in_gnt = data_in_gnt_i;
422	  assign buffer_full = read_buffer_full_i;
423	  assign buffer_alm_full = read_buffer_alm_full_i;
424	  assign dma_start = dma_start_i;
425	  assign dma_done_override = dma_done_override_i;
426	  assign read_ptr_update_sel = reg2hw.dim_inv.q;
427	  assign dma_conf_1d = reg2hw.dim_config.q == 0;
428	  assign dma_conf_2d = reg2hw.dim_config.q == 1;
429	  assign data_in_be_o = data_in_be;
430	  assign data_in_addr_o = data_in_addr;
431	  assign data_in_req_o = data_in_req;
432	  assign data_in_we_o = data_in_we;
433	  assign general_buffer_flush_o = buffer_flush;
434	  assign data_in_rvalid = data_in_rvalid_i;
435	  assign data_in_rdata = data_in_rdata_i;
436	  assign read_buffer_input_o = read_buffer_input;
437	  assign src_data_type = dma_data_type_t'(reg2hw.src_data_type.q);
438	  assign subaddr_mode = reg2hw.mode.q == 3;
439	
440	endmodule

